{"code": "# Let's check how many corrupted images there are
corrupted_files = []
valid_files = []

for root, dirs, files in os.walk('data_small/101/train'):
    for file in files:
        if file.endswith(('.jpg', '.jpeg', '.png')):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'rb') as f:
                    img = Image.open(f)
                    img.verify()
                valid_files.append(filepath)
            except Exception as e:
                corrupted_files.append((filepath, str(e)))

print(f"Total valid files: {len(valid_files)}")
print(f"Total corrupted files: {len(corrupted_files)}")
if corrupted_files:
    print("\nCorrupted files:")
    for f, e in corrupted_files[:10]:
        print(f"  {f}: {e}")"}

